for i, v in v2 do
    if not v.Model and RunService:IsServer() then
        warn(i, "has no attached model defaulting to Dog model");
        v.Model = v1:FindFirstChild("Dog");
    end;

    if v.Model and v.Model.Name ~= i then
        local v3 = v.Model:Clone();
        v3.Name = i;
        v3.Parent = v1;
    end;

    v.YHeightScaler = v.YHeightScaler or 0;
    v.States = v.States or {};
end;

return v2;